PRAGMA foreign_keys=ON;
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, payload JSON NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS businesses (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS financial_accounts (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS goals (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS assumptions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS actual_observations (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS scenarios (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL REFERENCES profiles(id) ON DELETE CASCADE, parent_id TEXT REFERENCES scenarios(id) ON DELETE CASCADE, payload JSON NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS simulation_runs (id TEXT PRIMARY KEY, scenario_id TEXT NOT NULL REFERENCES scenarios(id) ON DELETE CASCADE, payload JSON NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS life_states (id TEXT PRIMARY KEY, scenario_id TEXT NOT NULL REFERENCES scenarios(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS monthly_snapshots (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES simulation_runs(id) ON DELETE CASCADE, month INTEGER NOT NULL, payload JSON NOT NULL, UNIQUE(run_id, month));
CREATE TABLE IF NOT EXISTS decisions (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES simulation_runs(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS game_events (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES simulation_runs(id) ON DELETE CASCADE, payload JSON NOT NULL);
CREATE TABLE IF NOT EXISTS narrative_reports (id TEXT PRIMARY KEY, run_id TEXT NOT NULL REFERENCES simulation_runs(id) ON DELETE CASCADE, trajectory TEXT NOT NULL, payload JSON NOT NULL, UNIQUE(run_id, trajectory));
CREATE INDEX IF NOT EXISTS idx_scenarios_profile ON scenarios(profile_id);
CREATE INDEX IF NOT EXISTS idx_scenarios_parent ON scenarios(parent_id);
CREATE INDEX IF NOT EXISTS idx_runs_scenario ON simulation_runs(scenario_id);
CREATE INDEX IF NOT EXISTS idx_snapshots_run ON monthly_snapshots(run_id);
CREATE INDEX IF NOT EXISTS idx_businesses_profile ON businesses(profile_id);
CREATE INDEX IF NOT EXISTS idx_accounts_profile ON financial_accounts(profile_id);
CREATE INDEX IF NOT EXISTS idx_goals_profile ON goals(profile_id);
CREATE INDEX IF NOT EXISTS idx_assumptions_profile ON assumptions(profile_id);
CREATE INDEX IF NOT EXISTS idx_observations_profile ON actual_observations(profile_id);
CREATE INDEX IF NOT EXISTS idx_states_scenario ON life_states(scenario_id);
CREATE INDEX IF NOT EXISTS idx_decisions_run ON decisions(run_id);
CREATE INDEX IF NOT EXISTS idx_events_run ON game_events(run_id);
INSERT OR IGNORE INTO schema_migrations(version) VALUES (1);
COMMIT;
